#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;
using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using KingOfGraphic.Hero;
public sealed class HeroBusinessQA:MonoBehaviour{
 [Serializable]public class Check{public string name,detail;public bool pass;}
 [Serializable]public class Report{public string evidence="Controlled synthetic input and explicit API setup/business/damage calls; existing map physics; not natural play.";public List<Check> checks=new List<Check>();public List<string> observed=new List<string>();public bool completed;}
 public bool waterOnly;Report report=new Report();const string Root="ToolReports/HeroIntegration20261016/BusinessQA";HeroWorldAdapter hero;PlayerMovement move;PlayerVitals vitals;Health hp;HeroTraversal traversal;BaselineFlow flow;BaselineWorld world;Keyboard keyboard,priorK;Mouse mouse,priorM;GameObject source;bool restored;
 void Save(){Directory.CreateDirectory(Root);File.WriteAllText(Root+"/report.json",JsonUtility.ToJson(report,true));}
 void CheckIt(string name,bool pass,string detail){report.checks.Add(new Check{name=name,pass=pass,detail=detail});Save();}
 void LateUpdate(){if(!hero)return;foreach(var id in new[]{hero.CurrentAction,hero.pose.CurrentOverlay,hero.pose.RightHandGripActive?"HAND_GRIP_R":null})if(id!=null&&!report.observed.Contains(id)){report.observed.Add(id);Save();}}
 void Set(bool left=false,params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));InputSystem.QueueStateEvent(mouse,new MouseState{position=new Vector2(960,540)}.WithButton(MouseButton.Left,left));}
 IEnumerator Hold(float seconds,bool left=false,params Key[] keys){Set(left,keys);yield return new WaitForSecondsRealtime(seconds);Set();yield return null;}
 void Place(Vector3 p,float yaw=0){hero.CancelForTransition();vitals.Refill();move.Relocate(p,Quaternion.Euler(0,yaw,0));FindFirstObjectByType<ThirdPersonCamera>()?.ResetOrbit(yaw,18);Cursor.lockState=CursorLockMode.Locked;Cursor.visible=false;}
 void Damage(int amount,Vector3 direction){source.transform.position=hero.transform.position-direction*2;hp.TryApplyDamage(new DamageInfo(amount,source,hero.transform.position+Vector3.up,direction));}
 IEnumerator Start(){flow=FindFirstObjectByType<BaselineFlow>();if(!flow||flow.saveKeyPrefix!="QA.NativePlay.Hero20261016")yield break;if(!flow.Started)flow.ContinueGame();yield return new WaitForSecondsRealtime(.5f);
 hero=FindFirstObjectByType<HeroWorldAdapter>();move=hero.GetComponent<PlayerMovement>();vitals=hero.GetComponent<PlayerVitals>();hp=hero.GetComponent<Health>();traversal=hero.GetComponent<HeroTraversal>();world=FindFirstObjectByType<BaselineWorld>();priorK=Keyboard.current;priorM=Mouse.current;keyboard=InputSystem.AddDevice<Keyboard>("HeroBusinessSynthetic");mouse=InputSystem.AddDevice<Mouse>("HeroBusinessSyntheticMouse");keyboard.MakeCurrent();mouse.MakeCurrent();source=new GameObject("QA business damage source");
 Place(new Vector3(2,11.5f,-60));yield return new WaitForSecondsRealtime(.5f);yield return Hold(.06f,true);yield return new WaitForSecondsRealtime(.85f);CheckIt("finger_layer_active",hero.pose.RightHandGripActive,"Actual playable layer weight while drawn idle");Set(false,Key.Q);yield return new WaitForSecondsRealtime(.35f);Damage(1,Vector3.forward);yield return new WaitForSecondsRealtime(.1f);Set();yield return new WaitForSecondsRealtime(1);CheckIt("guard_break_behind",report.observed.Contains("GUARD_BREAK"),"Actual guarded player receives rear damage");
 Place(new Vector3(-78,2.4f,20));Set(false,Key.W);yield return new WaitForSecondsRealtime(3);Set(false,Key.W,Key.A);yield return new WaitForSecondsRealtime(1.6f);Set(false,Key.W,Key.D);yield return new WaitForSecondsRealtime(1.6f);Set();yield return new WaitForSecondsRealtime(.5f);CheckIt("swim_turns",report.observed.Contains("WATER_TURN_L")&&report.observed.Contains("WATER_TURN_R"),"Changed heading continuously while swimming");
 var waterLedge=HeroTraversalSurface.Available.First(x=>x.name=="Island water ledge grip");Place(waterLedge.Bottom-waterLedge.transform.forward*.35f);yield return new WaitForSecondsRealtime(1);bool wet=move.IsInWater;bool entered=traversal.TryEnter(waterLedge);yield return new WaitForSecondsRealtime(1.5f);CheckIt("water_ledge_grab",wet&&entered&&report.observed.Contains("WATER_LEDGE_GRAB"),"water="+wet+" entered="+entered+" root="+hero.transform.position);if(traversal.Active){yield return Hold(2.5f,false,Key.W);yield return new WaitForSecondsRealtime(2);CheckIt("water_ledge_exit",!traversal.Active,"root="+hero.transform.position+" contactError="+traversal.MaximumHandContactError);}
 if(waterOnly){Place(new Vector3(2,11.5f,-60));report.completed=true;Save();Restore();yield break;}
 Place(new Vector3(-2.59f,11.6f,-55.1f));yield return new WaitForSecondsRealtime(.7f);yield return Hold(.08f,false,Key.E);yield return new WaitForSecondsRealtime(1.4f);var dialog=FindFirstObjectByType<DialogueUI>();CheckIt("npc_touch_to_dialogue",report.observed.Contains("INTERACT_TOUCH")&&dialog.IsDialogueActive,"Existing NPC E interaction");ScreenCapture.CaptureScreenshot(Root+"/npc-touch-dialogue.png");if(dialog.IsDialogueActive)dialog.EndDialogue();yield return new WaitForSecondsRealtime(.4f);
 Place(new Vector3(2,17,-60));yield return new WaitForSecondsRealtime(.3f);Damage(999,Vector3.back);yield return new WaitForSecondsRealtime(.15f);var death=hero.GetComponent<MainWorldDeathUI>();CheckIt("air_death_before_ui",hero.CurrentAction=="DEATH_AIR"&&!death.IsOpen,"airborne death precedes modal");yield return new WaitForSecondsRealtime(3);CheckIt("death_ui_after_pose",death.IsOpen,"timeScale="+Time.timeScale);death.Retry();yield return new WaitForSecondsRealtime(1.6f);CheckIt("death_retry",!hp.IsDead&&!death.IsOpen&&Time.timeScale>0,"Existing Retry and private save");
 var item=FindObjectsByType<BaselineInteraction>(FindObjectsSortMode.None).FirstOrDefault(x=>x.action==BaselineInteraction.ActionKind.Chest&&x.index<2&&!world.opened[x.index]);if(item){var p=item.transform.position-Vector3.forward*1.7f;RaycastHit ground;if(Physics.Raycast(p+Vector3.up*5,Vector3.down,out ground,12,~0,QueryTriggerInteraction.Ignore))p.y=ground.point.y+.05f;Place(p);yield return new WaitForSecondsRealtime(.8f);int receipts=0;world.StateChanged+=()=>receipts++;world.Interact(item);world.Interact(item);yield return new WaitForSecondsRealtime(2);CheckIt("chest_event_once",report.observed.Contains("INTERACT_CHEST")&&world.opened[item.index]&&receipts==1,"Two API interaction attempts -> receipts="+receipts+" saved="+flow.Progress.opened[item.index]);ScreenCapture.CaptureScreenshot(Root+"/chest-contact-reward.png");world.GetComponent<BaselineRewardPresentation>()?.Dismiss();yield return new WaitForSecondsRealtime(.5f);world.Interact(item);yield return new WaitForSecondsRealtime(1.6f);CheckIt("chest_no_duplicate_reward",world.opened[item.index]&&!world.GetComponent<BaselineRewardPresentation>().IsOpen,"Already-collected receipt preserved");}
 Place(new Vector3(2,11.5f,-60));report.completed=true;Save();Restore();}
 void Restore(){if(restored)return;restored=true;Time.timeScale=1;if(keyboard!=null)InputSystem.RemoveDevice(keyboard);if(mouse!=null)InputSystem.RemoveDevice(mouse);priorK?.MakeCurrent();priorM?.MakeCurrent();if(source)Destroy(source);}
 void OnDestroy(){Save();Restore();}
}
